insomnia.test('HTTP 200', () => { insomnia.expect(insomnia.response.code).to.eql(200); });
if (insomnia.response.code === 200) {
  const body = insomnia.response.json();
  insomnia.test('Resposta contém somente token', () => {
    insomnia.expect(body.token).to.be.a('string');
    insomnia.expect(body).to.not.have.any.keys('password', 'passwordHash', 'senha', 'senha_hash');
  });
  if (body.token) insomnia.environment.set('admin_token', body.token);
}

